export function identFor(role: IdentRole, repo: Repository, env: NodeJS.ProcessEnv): Ident {
  const name = env[`GIT_${role}_NAME`] ?? repo.config.get("user.name");
  const email = env[`GIT_${role}_EMAIL`] ?? repo.config.get("user.email");
  if (name === undefined || email === undefined || name.trim() === "") {
    throw fatal("unable to auto-detect name and email address; set user.name and user.email");
  }
