/**
 * Marks the changed lines of both sides with xdiff's Myers diff (`xdl_do_diff` without a special
 * algorithm): common ends are trimmed, lines without a match are set aside, and the rest is compared.
 */
export function myersDiff(side1: DiffSide, side2: DiffSide): void {
  const n1 = side1.ha.length;
  const n2 = side2.ha.length;
  const lim = Math.min(n1, n2);
  let start = 0;
  while (start < lim && side1.ha[start] === side2.ha[start]) start++;
  let tail = 0;
  while (tail < lim - start && side1.ha[n1 - 1 - tail] === side2.ha[n2 - 1 - tail]) tail++;

  const e1 = cleanupRecords(side1, countClasses(side2.ha), start, n1 - tail - 1);
  const e2 = cleanupRecords(side2, countClasses(side1.ha), start, n2 - tail - 1);

  const ndiags = e1.ha.length + e2.ha.length + 3;
  const kvd = new Int32Array(2 * ndiags + 2);
  const fbase = e2.ha.length + 1;
  const bbase = ndiags + e2.ha.length + 1;
  const mxcost = Math.max(bogosqrt(ndiags), MAX_COST_MIN);

  // xdl_recs_cmp, with an explicit stack: the boxes are independent of each other.
  const stack: [number, number, number, number, boolean][] = [[0, e1.ha.length, 0, e2.ha.length, false]];
  for (let box = stack.pop(); box; box = stack.pop()) {
    let [off1, lim1, off2, lim2] = box;
    const needMin = box[4];
    while (off1 < lim1 && off2 < lim2 && e1.ha[off1] === e2.ha[off2]) {
      off1++;
      off2++;
    }
    while (off1 < lim1 && off2 < lim2 && e1.ha[lim1 - 1] === e2.ha[lim2 - 1]) {
      lim1--;
      lim2--;
    }
    if (off1 === lim1) {
      for (; off2 < lim2; off2++) setChanged(side2, e2.rindex[off2] ?? 0, true);
    } else if (off2 === lim2) {
      for (; off1 < lim1; off1++) setChanged(side1, e1.rindex[off1] ?? 0, true);
    } else {
      const spl = split(e1.ha, off1, lim1, e2.ha, off2, lim2, kvd, fbase, bbase, needMin, mxcost);
      stack.push([spl.i1, lim1, spl.i2, lim2, spl.minHi]);
      stack.push([off1, spl.i1, off2, spl.i2, spl.minLo]);
    }
  }
}

