/** What a command receives from the entry point. */
export interface CommandContext {
  /** The arguments after the command name. */
  args: string[];
  cwd: string;
  env: NodeJS.ProcessEnv;
  stdout: (text: string | Buffer) => void;
  stderr: (text: string) => void;
}

/** A command returns its exit code, or throws an `ExitError`. */
export type CommandRun = (ctx: CommandContext) => number;
/** Ends the command: the message goes to standard error and the process exits with `code`. */
export class ExitError extends Error {
  readonly code: number;

  constructor(message: string, code: number) {
    super(message);
    this.code = code;
  }
}

