cd /home/node/tgit; cat >> src/core/objects/commit.ts <<'EOF'

/** The message lines without the blank lines at the start and the end. */
export function messageLines(message: string): string[] {
  const lines = message.split("\n");
  while (lines.length > 0 && (lines[0] as string).trim() === "") lines.shift();
  while (lines.length > 0 && (lines.at(-1) as string).trim() === "") lines.pop();
  return lines;
}

/** The subject, as `--oneline` shows it: the lines of the first paragraph, joined with spaces. */
export function commitSubject(commit: Commit): string {
  const lines = messageLines(commit.message);
  const end = lines.indexOf("");
  return (end < 0 ? lines : lines.slice(0, end)).map((line) => line.trim()).join(" ");
}
