import { DIFF_DEFAULTS, diffLines, isBinary } from "./xdiff.ts";

const CONTEXT = 3;
const FUNC_NAME_WIDTH = 40;
const TRIM_BLOCK = 1024;
const NULL_ABBREV = "0000000";

export interface CombinedParent {
  /** The mode as a number, 0 if the parent does not have the path. */
