/**
 * Drops the common tail of two files in blocks of 1024 bytes, keeping whole lines, as the real git
 * does before a diff without context (`trim_common_tail`).
 */
function trimCommonTail(a: Buffer, b: Buffer): [Buffer, Buffer] {
  const smaller = Math.min(a.length, b.length);
  let trimmed = 0;
  while (TRIM_BLOCK + trimmed <= smaller) {
    const blockA = a.subarray(a.length - trimmed - TRIM_BLOCK, a.length - trimmed);
    const blockB = b.subarray(b.length - trimmed - TRIM_BLOCK, b.length - trimmed);
    if (!blockA.equals(blockB)) break;
    trimmed += TRIM_BLOCK;
  }
  const start = a.length - trimmed;
  let recovered = 0;
  while (recovered < trimmed) {
    if (a[start + recovered++] === 10) break;
  }
  const cut = trimmed - recovered;
  return [a.subarray(0, a.length - cut), b.subarray(0, b.length - cut)];
}

/**
 * Merges the lines lost from a new parent into the lines lost from earlier parents, matching
 * equal lines along a longest common subsequence (`coalesce_lines`).
 */
function coalesceLines(base: LostLine[], added: LostLine[], parent: number): LostLine[] {
  if (added.length === 0) return base;
  if (base.length === 0) return added;
  const MATCH = 1;
  const NEW = 2;
  const BASE = 3;
  const width = added.length + 1;
  const lcs = new Int32Array((base.length + 1) * width);
  const directions = new Uint8Array((base.length + 1) * width);
  for (let i = 0; i <= base.length; i++) directions[i * width] = BASE;
  for (let j = 1; j <= added.length; j++) directions[j] = NEW;
  for (let i = 1; i <= base.length; i++) {
    for (let j = 1; j <= added.length; j++) {
      const at = i * width + j;
      const left = lcs[at - 1] ?? 0;
      const up = lcs[at - width] ?? 0;
      if (base[i - 1]?.text.equals(added[j - 1]?.text ?? Buffer.alloc(0))) {
        lcs[at] = (lcs[at - width - 1] ?? 0) + 1;
        directions[at] = MATCH;
      } else if (left >= up) {
        lcs[at] = left;
        directions[at] = NEW;
      } else {
        lcs[at] = up;
        directions[at] = BASE;
      }
    }
