    return oid;
  });

  const abbreviator = new Abbreviator(repo.gitDir);
  const shown = oids.map((oid) => showCommit(repo.gitDir, oid, readCommit(repo.gitDir, oid) as Commit, abbreviator));
  ctx.stdout(Buffer.concat(shown.flatMap((entry, i) => (i === 0 ? [entry] : [Buffer.from("\n"), entry]))));
  return 0;
