// Random text files for the fuzz tests: few distinct lines, blank lines, and indentation, so that
// the diff algorithms meet repeated lines, sliders, and indent heuristics.

export function rng(seed: number): () => number {
  let h = seed >>> 0;
  return () => {
    h = (h + 0x6d2b79f5) | 0;
    let t = Math.imul(h ^ (h >>> 15), 1 | h);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const WORDS = ["a", "b", "c", "x", "}", "{", "", "int f()", "  return", "\treturn", "    if (x)", "foo", "bar", "baz"];

function randomLine(rand: () => number, vocabulary: number): string {
  if (rand() < 0.1) return `line ${Math.floor(rand() * 1000)}`;
  return WORDS[Math.floor(rand() * Math.min(vocabulary, WORDS.length))] ?? "";
}

function randomLines(rand: () => number, count: number, vocabulary: number): string[] {
  return Array.from({ length: count }, () => randomLine(rand, vocabulary));
}

function join(rand: () => number, lines: string[]): Buffer {
  if (lines.length === 0) return Buffer.alloc(0);
  return Buffer.from(lines.join("\n") + (rand() < 0.1 ? "" : "\n"));
}

function lengthFor(rand: () => number): number {
  const r = rand();
  if (r < 0.05) return 0;
  if (r < 0.85) return Math.floor(rand() * 40);
  if (r < 0.97) return 100 + Math.floor(rand() * 400);
  return 1000 + Math.floor(rand() * 3000);
}

export function randomFile(rand: () => number): Buffer {
  return join(rand, randomLines(rand, lengthFor(rand), 2 + Math.floor(rand() * WORDS.length)));
}

/** A modified copy of a file: lines inserted, deleted, replaced, and blocks moved. */
export function mutate(rand: () => number, data: Buffer): Buffer {
  const text = data.toString();
  const lines = text === "" ? [] : text.replace(/\n$/, "").split("\n");
  const edits = 1 + Math.floor(rand() * (lines.length > 200 ? 60 : 6));
  for (let e = 0; e < edits; e++) {
    const at = Math.floor(rand() * (lines.length + 1));
    const r = rand();
    if (r < 0.3) lines.splice(at, 0, ...randomLines(rand, 1 + Math.floor(rand() * 4), 8));
    else if (r < 0.6) lines.splice(at, 1 + Math.floor(rand() * 4));
    else if (r < 0.9) lines.splice(at, 1, ...randomLines(rand, 1 + Math.floor(rand() * 3), 8));
    else {
      const block = lines.splice(at, 1 + Math.floor(rand() * 10));
      lines.splice(Math.floor(rand() * (lines.length + 1)), 0, ...block);
    }
  }
  return join(rand, lines);
}
// Compares tgit's line diff with the real git's on random file pairs, using `git diff --no-index`.
// Usage: node test/fuzz/diff-fuzz.ts [--count 500] [--seed 1] [--algorithm myers|histogram]
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { parseArgs } from "node:util";
import { formatHunks } from "../../src/core/diff/unified.ts";
import { DIFF_DEFAULTS, MERGE_DEFAULTS, diffLines } from "../../src/core/diff/xdiff.ts";
import { randomFile, mutate, rng } from "./random-text.ts";

const { values } = parseArgs({
  options: {
    count: { type: "string", default: "500" },
    seed: { type: "string", default: "1" },
    algorithm: { type: "string", default: "myers" },
  },
});
const histogram = values.algorithm === "histogram";
const options = histogram ? MERGE_DEFAULTS : DIFF_DEFAULTS;
const flags = histogram ? ["--histogram", "--no-indent-heuristic"] : [];

const dir = fs.mkdtempSync(path.join(os.tmpdir(), "tgit-diff-fuzz-"));
const env = { ...process.env, HOME: dir, GIT_CONFIG_NOSYSTEM: "1", LANG: "C", LC_ALL: "C" };
const rand = rng(Number(values.seed));
let failures = 0;
for (let n = 0; n < Number(values.count); n++) {
  const a = randomFile(rand);
  // Sometimes unrelated files, so that large edit costs reach the heuristics and cost limits.
  const b = rand() < 0.1 ? randomFile(rand) : mutate(rand, a);
  const fa = path.join(dir, "a");
  const fb = path.join(dir, "b");
  fs.writeFileSync(fa, a);
  fs.writeFileSync(fb, b);
  const git = spawnSync("git", ["diff", "--no-index", ...flags, "a", "b"], { cwd: dir, env });
  const out = git.stdout;
  const at = out.indexOf("\n@@ ");
  const expected = at < 0 ? Buffer.alloc(0) : out.subarray(at + 1);
  const actual = formatHunks(diffLines(a, b, options));
  if (!expected.equals(actual)) {
    failures++;
    const keep = path.join(os.tmpdir(), `tgit-diff-fail-${values.seed}-${n}`);
    fs.mkdirSync(keep, { recursive: true });
    fs.writeFileSync(path.join(keep, "a"), a);
    fs.writeFileSync(path.join(keep, "b"), b);
    fs.writeFileSync(path.join(keep, "expected"), expected);
    fs.writeFileSync(path.join(keep, "actual"), actual);
    console.log(`mismatch #${n}: ${keep}`);
    if (failures >= 5) break;
  }
}
fs.rmSync(dir, { recursive: true, force: true });
console.log(failures === 0 ? "all matched" : `${failures} mismatches`);
process.exitCode = failures === 0 ? 0 : 1;

