    if (arg === "--") {
      ctx.stdout(`${[arg, ...ctx.args.slice(i + 1)].join("\n")}\n`);
      return 0;
    }
    if (arg.startsWith("-")) {
      ctx.stdout(`${arg}\n`);
      continue;
